package dev.veltraph.client.builder;
import dev.veltraph.client.config.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Uses the SAME policy.validate path called by paid-leg adapter at message/action/ACK/completion boundaries. */
class Source95PolicyRevocationTest {
 @org.junit.jupiter.api.io.TempDir java.nio.file.Path dir;
 private static final String CONTRACT="{\"WHEAT\":{\"productName\":\"Seeds\",\"resourceComponents\":\"@vanilla\",\"menuTitles\":[\"Seeds\"],\"controls\":{\"instant\":\"Instant\",\"stack\":\"Stack\"},\"maxTotalCoins\":500,\"clickDelayMillis\":100,\"timeoutMillis\":30000}}";
 private MapConfigService config(){var c=new MapConfigService();c.set(BuilderConfig.BUILDER_BUY_RESOURCES,true);c.set(GeneratedBuilderConfig.IRONMAN_MODE,false);c.set(BuilderConfig.BUILDER_CROP_TYPE,BuilderCropType.WHEAT);c.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT);return c;}
 private Source95AcquisitionAuthority.Scope scope(){return new Source95AcquisitionAuthority.Scope(new Object(),new Object(),new Object(),new Object(),new Object(),new Object(),2,3);}
 private void changed(java.util.function.Consumer<MapConfigService> change,boolean partial){var c=config();var b=Source95AcquisitionBinding.decode(CONTRACT,BuilderCropType.WHEAT);var p=new Source95AcquisitionPolicy(b);var a=new Source95AcquisitionAuthority();var s=scope();assertTrue(p.validate(c,a));assertTrue(a.issueLeg(b,s,64,192,127,10,0));if(partial){assertTrue(a.acknowledgeLeg(s,191,64,192,true,11,true,true,1));assertTrue(a.issueLeg(b,s,64,192,191,11,2));}change.accept(c);assertFalse(p.validate(c,a));assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,a.state());assertFalse(a.acknowledgeLeg(s,partial?255:191,64,192,true,12,true,true,3));assertFalse(a.issueLeg(b,s,64,192,partial?255:191,12,4));assertEquals(partial?64:0,a.acquired());assertEquals(partial?192:0,a.spent());assertTrue(a.unknownOutcome().isPresent());}
 @Test void lowerCapAfterPaidDispatchCannotAuthorizeLateAck(){changed(c->c.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT.replace("500","100")),false);changed(c->c.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT.replace("500","300")),true);}
 @Test void cropPurchaseIronmanAndContractRevocationPoisonPendingFirstAndSecondLegs(){for(boolean partial:List.of(false,true)){changed(c->c.set(BuilderConfig.BUILDER_CROP_TYPE,BuilderCropType.CARROT),partial);changed(c->c.set(BuilderConfig.BUILDER_BUY_RESOURCES,false),partial);changed(c->c.set(GeneratedBuilderConfig.IRONMAN_MODE,true),partial);changed(c->c.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT.replace("Stack","Other")),partial);}}
 @Test void perKeyWriteEpochDetectsEveryRelevantKeyABABetweenPaidBoundaryReads(){
  for(boolean partial:List.of(false,true)){
   changed(c->{c.set(BuilderConfig.BUILDER_BUY_RESOURCES,false);c.set(BuilderConfig.BUILDER_BUY_RESOURCES,true);},partial);
   changed(c->{c.set(GeneratedBuilderConfig.IRONMAN_MODE,true);c.set(GeneratedBuilderConfig.IRONMAN_MODE,false);},partial);
   changed(c->{c.set(BuilderConfig.BUILDER_CROP_TYPE,BuilderCropType.CARROT);c.set(BuilderConfig.BUILDER_CROP_TYPE,BuilderCropType.WHEAT);},partial);
   changed(c->{c.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT.replace("Stack","Other"));c.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT);},partial);
  }
 }
 @Test void equalWritesAndUnrelatedKeyChangesPreserveValidPendingPaidLeg(){var c=config();var b=Source95AcquisitionBinding.decode(CONTRACT,BuilderCropType.WHEAT);var p=new Source95AcquisitionPolicy(b);var a=new Source95AcquisitionAuthority();var s=scope();assertTrue(p.validate(c,a));assertTrue(a.issueLeg(b,s,64,192,127,10,0));c.set(BuilderConfig.BUILDER_BUY_RESOURCES,true);c.set(GeneratedBuilderConfig.IRONMAN_MODE,false);c.reset(GeneratedBuilderConfig.IRONMAN_MODE);c.set(BuilderConfig.BUILDER_CROP_TYPE,BuilderCropType.WHEAT);c.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT);c.set(ConfigKey.ofBool("UNRELATED_OBSERVER",false),true);assertTrue(p.validate(c,a));assertEquals(0,p.generation());assertTrue(p.revisionEvidenceAvailable());assertTrue(a.acknowledgeLeg(s,191,64,192,true,11,true,true,1));}
 @Test void resetAndRestoreContractAfterPaidDispatchCannotHideRevocation(){for(boolean partial:List.of(false,true))changed(c->{c.reset(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING);c.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT);},partial);}
 @Test void durableReloadABAAcrossEveryRelevantKeyIsDetectedAtPendingPaidBoundary()throws Exception{
  var keys=List.<ConfigKey<?>>of(BuilderConfig.BUILDER_BUY_RESOURCES,GeneratedBuilderConfig.IRONMAN_MODE,BuilderConfig.BUILDER_CROP_TYPE,GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING);
  for(boolean partial:List.of(false,true))for(int key=0;key<4;key++){
   var original=new LinkedHashMap<String,Object>();original.put(BuilderConfig.BUILDER_BUY_RESOURCES.name(),true);original.put(GeneratedBuilderConfig.IRONMAN_MODE.name(),false);original.put(BuilderConfig.BUILDER_CROP_TYPE.name(),BuilderCropType.WHEAT);original.put(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING.name(),CONTRACT);
   var c=new JsonConfigService(keys);var path=dir.resolve("pending-"+partial+"-"+key+".json");java.nio.file.Files.writeString(path,ConfigCodec.encode(original,List.of()));c.load(path,null);
   var b=Source95AcquisitionBinding.decode(CONTRACT,BuilderCropType.WHEAT);var p=new Source95AcquisitionPolicy(b);var a=new Source95AcquisitionAuthority();var s=scope();assertTrue(p.validate(c,a));assertTrue(a.issueLeg(b,s,64,192,127,10,0));if(partial){assertTrue(a.acknowledgeLeg(s,191,64,192,true,11,true,true,1));assertTrue(a.issueLeg(b,s,64,192,191,11,2));}
   var changed=new LinkedHashMap<>(original);changed.put(keys.get(key).name(),switch(key){case 0->false;case 1->true;case 2->BuilderCropType.CARROT;case 3->CONTRACT.replace("Stack","Other");default->throw new AssertionError();});java.nio.file.Files.writeString(path,ConfigCodec.encode(changed,List.of()));c.load(path,null);java.nio.file.Files.writeString(path,ConfigCodec.encode(original,List.of()));c.load(path,null);assertFalse(c.isDirty());assertFalse(p.validate(c,a));assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,a.state());assertFalse(a.acknowledgeLeg(s,partial?255:191,64,192,true,12,true,true,3));assertEquals(partial?64:0,a.acquired());
  }
 }
 @Test void observedABAStaysRevokedWithoutRevisionButUnobservedABAIsExplicitlyUnavailable(){var backing=config();ConfigService bare=new ConfigService(){public <T>T get(ConfigKey<T> k){return backing.get(k);}public <T>void set(ConfigKey<T> k,T v){backing.set(k,v);}public boolean isSet(ConfigKey<?> k){return backing.isSet(k);}public void reset(ConfigKey<?> k){backing.reset(k);}};var b=Source95AcquisitionBinding.decode(CONTRACT,BuilderCropType.WHEAT);var p=new Source95AcquisitionPolicy(b);var a=new Source95AcquisitionAuthority();assertTrue(p.validate(bare,a));assertFalse(p.revisionEvidenceAvailable());bare.set(GeneratedBuilderConfig.IRONMAN_MODE,true);assertFalse(p.validate(bare,a));bare.set(GeneratedBuilderConfig.IRONMAN_MODE,false);assertFalse(p.validate(bare,a));var fresh=new Source95AcquisitionPolicy(b);var other=new Source95AcquisitionAuthority();assertTrue(fresh.validate(bare,other));bare.set(GeneratedBuilderConfig.IRONMAN_MODE,true);bare.set(GeneratedBuilderConfig.IRONMAN_MODE,false);assertTrue(fresh.validate(bare,other));assertFalse(fresh.revisionEvidenceAvailable());}
 @Test void authorizationChangeAfter128KnownBeforeCompletionStillForbidsDestructiveAdvance(){var c=config();var b=Source95AcquisitionBinding.decode(CONTRACT,BuilderCropType.WHEAT);var p=new Source95AcquisitionPolicy(b);var a=new Source95AcquisitionAuthority();var s=scope();p.validate(c,a);a.issueLeg(b,s,64,192,127,10,0);a.acknowledgeLeg(s,191,64,192,true,11,true,true,1);a.issueLeg(b,s,64,192,191,11,2);a.acknowledgeLeg(s,255,64,192,true,12,true,true,3);assertEquals(Source95AcquisitionAuthority.State.CONFIRMED,a.state());c.set(BuilderConfig.BUILDER_BUY_RESOURCES,false);assertFalse(p.validate(c,a));assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,a.state());assertEquals(128,a.acquired());assertEquals(384,a.spent());}
}
